(function() {
    'use strict';

    class CyberSecurityAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'La Ciberseguridad';
            this.version = '1.1.0';
            // Pre-round domainState snapshots so Undo can roll state back instead
            // of re-accumulating on resubmit (see initialize / calculateResults).
            this._snap = [];
            this.ROUND_CONFIGS = [
                { budgetMin: 50, budgetMax: 300, budgetDefault: 150 },
                { budgetMin: 0, budgetMax: 5000, budgetDefault: 2000 },
                { budgetMin: 50, budgetMax: 500, budgetDefault: 200 },
                { budgetMin: 100, budgetMax: 2000, budgetDefault: 500 }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 5000000,
                    reputation: 100,
                    dataIntegrity: 0,
                    securityLevel: 15,
                    compliance: 50,
                    forensicQuality: 0,
                    ransomPaid: false,
                    totalSpent: 0,
                    costHistory: [],
                    reputationHistory: [],
                    securityHistory: [],
                    dataHistory: [],
                    events: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    budget: 150,
                    strategy: 1
                };
            }
            // Undo support: the framework's Undo pops the last history row,
            // decrements currentPeriod and re-calls initialize() WITHOUT rolling
            // domainState back. If we hold more snapshots than history rows, an
            // Undo just happened -> restore the pre-round domainState so cash /
            // reputation / security / data / history revert instead of drifting.
            var histLen = (state.history && state.history.length) || 0;
            if (this._snap && this._snap.length > histLen) {
                state.domainState = this._snap.pop();
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, 3);
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t('round' + (idx + 1) + '_briefing');

            var budgetLabel = document.getElementById('budgetLabel');
            var budgetInput = document.getElementById('budgetInput');
            var budgetHint = document.getElementById('budgetHint');
            var strategyLabel = document.getElementById('strategyLabel');
            var strategySelect = document.getElementById('strategySelect');

            var cfg = this.ROUND_CONFIGS[idx];

            if (budgetLabel) budgetLabel.textContent = t('round' + (idx + 1) + '_budget_label');
            if (budgetInput) {
                budgetInput.min = cfg.budgetMin;
                budgetInput.max = cfg.budgetMax;
                budgetInput.value = cfg.budgetDefault;
            }
            if (budgetHint) budgetHint.textContent = t('round' + (idx + 1) + '_budget_hint');
            if (strategyLabel) strategyLabel.textContent = t('round' + (idx + 1) + '_strategy_label');
            if (strategySelect) {
                var optHtml = '';
                for (var o = 1; o <= 3; o++) {
                    optHtml += '<option value="' + o + '">' + t('round' + (idx + 1) + '_opt' + o) + '</option>';
                }
                strategySelect.innerHTML = optHtml;
            }

            var eventEl = document.getElementById('eventLog');
            if (eventEl && window.mySimulation && window.mySimulation.state) {
                var evts = window.mySimulation.state.domainState.events || [];
                eventEl.innerHTML = evts.join('<br>');
            }
        }

        validateDecisions(decisions) {
            var budgetInput = document.getElementById('budgetInput');
            if (budgetInput) decisions.budget = parseFloat(budgetInput.value);

            var strategySelect = document.getElementById('strategySelect');
            if (strategySelect) decisions.strategy = parseInt(strategySelect.value);

            var idx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, 3);
            var cfg = this.ROUND_CONFIGS[idx];

            if (isNaN(decisions.budget) || decisions.budget < cfg.budgetMin || decisions.budget > cfg.budgetMax) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.strategy || decisions.strategy < 1 || decisions.strategy > 3) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('strategy_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            // Snapshot the pre-round domainState (serializable) so Undo can roll it
            // back in initialize() instead of re-accumulating on resubmit.
            this._snap.push(JSON.parse(JSON.stringify(ds)));
            var period = state.currentPeriod;
            var cost = 0;
            var repDelta = 0;
            var dataDelta = 0;
            var secDelta = 0;
            var compDelta = 0;
            var eventText = '';
            var t = window.mySimulation.t.bind(window.mySimulation);

            if (period === 1) {
                cost = d.budget * 1000;
                if (d.strategy === 2) cost += 50000;
                if (d.strategy === 3) cost += 100000;
                ds.forensicQuality = Math.min(1, d.budget / 300);
                repDelta = d.strategy === 3 ? 0 : d.strategy === 2 ? -5 : -15;
                secDelta = 0;
                dataDelta = 0;
                eventText = t('event_r1_forensic') + ' (' + Math.round(ds.forensicQuality * 100) + '%)';
                if (d.strategy === 3) {
                    eventText += '<br>' + t('event_r1_full_activation');
                } else if (d.strategy === 2) {
                    eventText += '<br>' + t('event_r1_board_alert');
                } else {
                    eventText += '<br>' + t('event_r1_containment');
                }
            }

            if (period === 2) {
                if (d.strategy === 1) {
                    cost = 475000;
                    var successRate = ds.forensicQuality > 0.7 ? 0.9 : 0.8;
                    var roll = Math.random();
                    if (roll < successRate) {
                        dataDelta = 89 - ds.dataIntegrity;
                        eventText = t('event_r2_pay_success');
                    } else {
                        dataDelta = 45 - ds.dataIntegrity;
                        eventText = t('event_r2_pay_partial');
                    }
                    repDelta = -15;
                    secDelta = 0;
                    ds.ransomPaid = true;
                    var residualRoll = Math.random();
                    if (ds.forensicQuality < 0.5 && residualRoll < 0.3) {
                        secDelta = -10;
                        eventText += '<br>' + t('event_r2_malware_detected');
                    }
                } else if (d.strategy === 2) {
                    cost = Math.max(d.budget, 500) * 1000;
                    dataDelta = Math.min(78, (Math.max(d.budget, 500) / 3200) * 78) - ds.dataIntegrity;
                    repDelta = 5;
                    secDelta = 15;
                    ds.ransomPaid = false;
                    eventText = t('event_r2_rebuild');
                } else {
                    cost = 475000 + Math.max(d.budget, 200) * 1000;
                    dataDelta = Math.min(92, 89 + (Math.max(d.budget, 200) / 2000) * 3) - ds.dataIntegrity;
                    repDelta = -5;
                    secDelta = 10;
                    ds.ransomPaid = true;
                    eventText = t('event_r2_hybrid');
                }
            }

            if (period === 3) {
                var baseLegal = d.strategy === 1 ? 100000 : d.strategy === 2 ? 150000 : 300000;
                cost = d.budget * 1000 + baseLegal;
                compDelta = d.strategy === 1 ? 30 : d.strategy === 2 ? 15 : -20;
                if (ds.ransomPaid) compDelta -= 10;
                var commEffect = Math.min(1, d.budget / 500);
                var timingRep = d.strategy === 1 ? 10 : d.strategy === 2 ? 5 : -10;
                repDelta = Math.round(commEffect * 15 + timingRep);
                secDelta = 0;
                dataDelta = 2;
                if (d.strategy === 1) {
                    eventText = t('event_r3_immediate');
                } else if (d.strategy === 2) {
                    eventText = t('event_r3_within48');
                } else {
                    eventText = t('event_r3_delayed');
                }
                if (ds.ransomPaid) {
                    eventText += '<br>' + t('event_r3_aml_risk');
                }
            }

            if (period === 4) {
                var insuranceCost = d.strategy === 3 ? 180000 : d.strategy === 2 ? 90000 : 0;
                cost = d.budget * 1000 + insuranceCost;
                secDelta = Math.round(Math.min(70, (d.budget / 2000) * 70));
                repDelta = 10;
                dataDelta = 5;
                compDelta = d.strategy >= 2 ? 10 : 0;
                eventText = t('event_r4_security');
                if (d.strategy === 3) {
                    eventText += '<br>' + t('event_r4_insurance_full');
                } else if (d.strategy === 2) {
                    eventText += '<br>' + t('event_r4_insurance_basic');
                } else {
                    eventText += '<br>' + t('event_r4_no_insurance');
                }
            }

            ds.cash -= cost;
            ds.totalSpent += cost;
            ds.reputation = Math.max(0, Math.min(100, ds.reputation + repDelta));
            ds.dataIntegrity = Math.max(0, Math.min(100, Math.round(ds.dataIntegrity + dataDelta)));
            ds.securityLevel = Math.max(0, Math.min(100, ds.securityLevel + secDelta));
            ds.compliance = Math.max(0, Math.min(100, ds.compliance + compDelta));

            ds.costHistory.push(cost);
            ds.reputationHistory.push(ds.reputation);
            ds.securityHistory.push(ds.securityLevel);
            ds.dataHistory.push(ds.dataIntegrity);
            ds.events.push('<b>R' + period + ':</b> ' + eventText);

            var results = {
                period: period,
                budget: d.budget,
                strategy: d.strategy,
                cost: cost,
                reputationDelta: repDelta,
                dataDelta: Math.round(dataDelta),
                secDelta: secDelta,
                cash: ds.cash,
                reputation: ds.reputation,
                dataIntegrity: ds.dataIntegrity,
                securityLevel: ds.securityLevel,
                compliance: ds.compliance
            };

            // Advance the briefing / decision controls to the next round SYNCHRONOUSLY.
            // The framework increments currentPeriod right after this returns, so the
            // old deferred setTimeout read the already-incremented period and rendered
            // the round-after-next's briefing + budget range + strategy options (after
            // Round 1 it showed Round 3's controls while validateDecisions still scored
            // Round 2). currentPeriod is still N here, so N+1 is correct. Skip past the
            // last round.
            if (state.currentPeriod < this.ROUND_CONFIGS.length) {
                this._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('reputationDisplay', 'domainState.reputation',
                function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('dataDisplay', 'domainState.dataIntegrity',
                function(v) { return Math.round(v) + '%'; });
            uiManager.bind('securityDisplay', 'domainState.securityLevel',
                function(v) { return Math.round(v) + '%'; });
        }

        getChartConfig() {
            return {
                costChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Round Cost ($)',
                            data: [],
                            backgroundColor: [
                                'rgba(255,68,68,0.7)',
                                'rgba(255,68,68,0.7)',
                                'rgba(255,68,68,0.7)',
                                'rgba(255,68,68,0.7)'
                            ],
                            borderColor: '#ff4444',
                            borderWidth: 2,
                            borderRadius: 4
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Cost Per Round', color: '#8b949e' },
                            legend: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                ticks: { color: '#6b7280', callback: function(v) { return '$' + (v / 1000) + 'K'; } },
                                grid: { color: 'rgba(31,45,61,0.5)' }
                            },
                            x: {
                                ticks: { color: '#6b7280' },
                                grid: { display: false }
                            }
                        }
                    }
                },
                scoreChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Reputation',
                                data: [],
                                borderColor: '#00bfff',
                                backgroundColor: 'rgba(0,191,255,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.3,
                                pointRadius: 5,
                                pointBackgroundColor: '#00bfff'
                            },
                            {
                                label: 'Data Integrity',
                                data: [],
                                borderColor: '#ffaa00',
                                backgroundColor: 'rgba(255,170,0,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.3,
                                pointRadius: 5,
                                pointBackgroundColor: '#ffaa00'
                            },
                            {
                                label: 'Security Level',
                                data: [],
                                borderColor: '#00ff88',
                                backgroundColor: 'rgba(0,255,136,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.3,
                                pointRadius: 5,
                                pointBackgroundColor: '#00ff88'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Key Metrics Over Time', color: '#8b949e' },
                            legend: { labels: { color: '#8b949e', boxWidth: 12, padding: 10 } }
                        },
                        scales: {
                            y: {
                                min: 0,
                                max: 100,
                                ticks: { color: '#6b7280' },
                                grid: { color: 'rgba(31,45,61,0.5)' }
                            },
                            x: {
                                ticks: { color: '#6b7280' },
                                grid: { display: false }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.costHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                costChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.costHistory }]
                },
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.reputationHistory },
                        { data: state.domainState.dataHistory },
                        { data: state.domainState.securityHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds = last.domainState || {};
            var rep = ds.reputation || 0;
            var data = ds.dataIntegrity || 0;
            var sec = ds.securityLevel || 0;
            var comp = ds.compliance || 0;
            var totalSpent = ds.totalSpent || 0;
            var ransomPaid = ds.ransomPaid || false;

            var compositeScore = Math.round((rep * 0.25) + (data * 0.25) + (sec * 0.25) + (comp * 0.25));

            var performance = 'Needs Improvement';
            if (compositeScore >= 75) performance = 'Excellent Cyber Resilience';
            else if (compositeScore >= 60) performance = 'Strong Crisis Management';
            else if (compositeScore >= 45) performance = 'Adequate Response';

            var insights = [];
            if (ransomPaid) {
                insights.push('Paying the ransom reduced costs but introduced legal and ethical risks.');
            } else {
                insights.push('Not paying the ransom was the principled choice, though more expensive.');
            }
            if (sec >= 70) {
                insights.push('Strong post-crisis security investment will protect against future attacks.');
            } else {
                insights.push('Security investment may be insufficient to prevent future incidents.');
            }
            if (rep >= 70) {
                insights.push('Reputation was well managed through the crisis.');
            } else {
                insights.push('Reputation took significant damage during the crisis.');
            }
            if (data < 80) {
                insights.push('Data recovery was incomplete. Better backup policies would have prevented this.');
            }
            insights.push('Preventive cybersecurity investment ($500K) would have been 10x cheaper than this crisis ($' + Math.round(totalSpent / 1000) + 'K).');

            return {
                compositeScore: compositeScore,
                totalSpent: totalSpent,
                reputation: rep,
                dataIntegrity: data,
                securityLevel: sec,
                compliance: comp,
                ransomPaid: ransomPaid,
                performance: performance,
                insights: insights
            };
        }

